<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Admin; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class AuthController extends Controller { public function form(){return view('admin.login');} public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string']);$a=Admin::where('email',$d['email'])->where('is_active',true)->first();if(!$a||!Hash::check($d['password'],$a->password))return back()->withErrors(['email'=>'Invalid credentials.'])->onlyInput('email');$r->session()->regenerate();$r->session()->put('admin_id',$a->id);return redirect()->route('admin.dashboard');} public function logout(Request $r){$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('admin.login');}}
